CAPS={'NO_BOUNDARY':[],'SINGLE_BOUNDARY':['dependency_install_new'],'REPEATED_SAME_BOUNDARY':['dependency_install_new','dependency_install_new'],'SEQUENTIAL_NEW_BOUNDARIES':['dependency_install_new','config_modification']}
